function rect(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),w,h);}function text(c,s,x,y,size=12,color='#e5d8ae'){c.font='bold '+size+'px monospace';c.textAlign='center';c.fillStyle='#1b1822';c.fillText(s,x+1,y+2);c.fillStyle=color;c.fillText(s,x,y);}function line(c,x,y,X,Y,color,w=1){c.strokeStyle=color;c.lineWidth=w;c.beginPath();c.moveTo(x,y);c.lineTo(X,Y);c.stroke();}
